def test_code_chunk_title_is_first_definition():
    src = "import x\n\n\nclass Grid:\n    pass\n" + "\n".join(f"a{i} = 1" for i in range(30))
    assert chunk_file("r", "g.py", src)[0].title == "g.py › Grid"


def test_html_text_is_visible_text_only():
    html = "<html>\n<style>\n.a{color:red}\n</style>\n<body>\n<h1>Hello &amp; welcome</h1>\n<script>var x=1;</script>\n<p>" + "text " * 20 + "</p>\n</body></html>"
    c = chunk_file("r", "index.html", html)[0]
    assert "Hello & welcome" in c.text
    assert "color" not in c.text and "var x" not in c.text


def test_bidi_marks_are_removed():
    c = chunk_file("r", "notes.md", "# כותרת\nטקסט עם סימני כיוון " + "מילה " * 20)[0]
    assert "" not in c.text and "" not in c.text


# ---------------------------------------------------------------- search
def _kb():
    def ch(repo, path, text, title="", kind="code"):
        return {"id": f"{repo}:{path}:1-5", "repo": repo, "path": path, "start": 1, "end": 5,
                "title": title or path, "kind": kind, "text": text}
    chunks = [
        ch("game", "game/ai.py", "def find_path_step(start, goal): breadth first search queue for the enemy chase"),
        ch("game", "tests/test_ai.py", "def test_find_path_step(): enemy chase breadth first search"),
        ch("game", "game/bombs.py", "explode bomb chain reaction flame"),
        ch("game", "game/bombs.py", "another bomb chunk with chain reaction and more chain"),
        ch("game", "game/bombs.py", "third bomb chunk chain reaction"),
        ch("fit", "client/engine.ts", "count reps with a state machine and hysteresis on joint angles"),
        ch("fit", "README.md", "FitVision counts reps from the camera", kind="doc"),
    ]
    tok = {"stopwords": [], "glossary": {}, "aliases": {}, "prefix1": "", "prefix2": []}
    return {"repos": [{"key": "game", "url": "https://github.com/u/game", "branch": "main"},
                      {"key": "fit", "url": "https://github.com/u/fit", "branch": "main"}],
            "chunks": chunks, "tokenizer": tok}


def test_bm25_ranks_the_implementation_first():
    ix = Index(_kb())
    hits = ix.search("how does the enemy chase work", k=3)
    assert hits[0].chunk["path"] == "game/ai.py"   # the test file is penalised


def test_tests_win_when_asked_for():
    ix = Index(_kb())
    assert ix.search("tests for enemy chase", k=1)[0].chunk["path"] == "tests/test_ai.py"

def test_offline_mode_answers_with_excerpts():
    from yakovllm import llm
    hits = [{"n": 1, "repo": "r", "path": "a.py", "start": 1, "end": 3, "kind": "code", "text": "def f():\n    pass"}]
    text = "".join(llm.offline_answer("how?", hits))
    assert "a.py" in text and "```py" in text and "[1]" in text


# ---------------------------------------------------------------- parity + quality
@pytest.mark.skipif(not shutil.which("node"), reason="node not installed")
def test_browser_engine_matches_python():
    script = f"""
      const {{Index}} = require({json.dumps(str(ROOT / 'web' / 'engine.js'))});
      const fs = require('fs');
      const kb = JSON.parse(fs.readFileSync({json.dumps(str(ROOT / 'data' / 'kb.json'))}, 'utf8'));
      const qs = JSON.parse(fs.readFileSync({json.dumps(str(ROOT / 'eval' / 'questions.json'))}, 'utf8'));
      const ix = new Index(kb);
      console.log(JSON.stringify(qs.map(q => ix.search(q.q, {{k: 8}}).map(h => [h.chunk.id, h.score]))));
    """
    js = json.loads(subprocess.run(["node", "-e", script], capture_output=True, text=True, check=True).stdout)
    ix = Index.load(ROOT / "data" / "kb.json")
    qs = json.loads((ROOT / "eval" / "questions.json").read_text(encoding="utf-8"))
    for q, j in zip(qs, js):
        py = [[h.chunk["id"], h.score] for h in ix.search(q["q"], k=8)]
        assert [a for a, _ in py] == [a for a, _ in j], q["q"]
        assert all(abs(a[1] - b[1]) < 1e-6 for a, b in zip(py, j))


def test_retrieval_quality_does_not_regress():
    sys.path.insert(0, str(ROOT / "eval"))
    from run_eval import evaluate
    ix = Index.load(ROOT / "data" / "kb.json")
    qs = json.loads((ROOT / "eval" / "questions.json").read_text(encoding="utf-8"))
    r = evaluate(ix, qs)
    assert r["all"]["hit@5"] >= 0.80, r["all"]


def test_cors_lets_the_static_demo_call_the_api(app):
    _, url = app
    allowed = urllib.request.Request(url + "/api/health", headers={"Origin": "https://yakov-ashgar27.github.io"})
    assert urllib.request.urlopen(allowed).headers["Access-Control-Allow-Origin"] == "https://yakov-ashgar27.github.io"
    other = urllib.request.Request(url + "/api/health", headers={"Origin": "https://evil.example"})
    assert urllib.request.urlopen(other).headers["Access-Control-Allow-Origin"] is None
    pre = urllib.request.Request(url + "/api/chat", method="OPTIONS", headers={"Origin": "https://yakov-ashgar27.github.io"})
    r = urllib.request.urlopen(pre)
    assert r.status == 204 and "POST" in r.headers["Access-Control-Allow-Methods"]


