    langs = ", ".join(f"{k} ({v})" for k, v in meta["languages"].items())
    lines = [
        f"# {meta['title']} ({meta['name']})",
        f"Project overview / סקירת הפרויקט {meta['name']}.",
        meta.get("description") or "",
