class Index:
    def __init__(self, kb: dict):
        self.kb = kb
        self.repos = {r["key"]: r for r in kb["repos"]}
        self.chunks: list[dict] = kb["chunks"]
        self.postings: dict[str, list[tuple[int, int]]] = defaultdict(list)
        self.lengths: list[int] = []
        for i, c in enumerate(self.chunks):
            meta = f'{c["repo"]} {c["path"].replace("/", " ").replace(".", " ")} {c["title"]}'
            counts = Counter(tokenizer.tokenize(c["text"]))
            for t in tokenizer.tokenize(meta):
                counts[t] += META_WEIGHT
            self.lengths.append(sum(counts.values()))
            for t, tf in counts.items():
                self.postings[t].append((i, tf))
        self.n = len(self.chunks)
        self.avg_len = (sum(self.lengths) / self.n) if self.n else 1.0

    @classmethod
    def load(cls, path: str | Path) -> "Index":
        return cls(json.loads(Path(path).read_text(encoding="utf-8")))

    def idf(self, term: str) -> float:
        df = len(self.postings.get(term, ()))
        return math.log(1 + (self.n - df + 0.5) / (df + 0.5))

    def search(self, query: str, k: int = 6, repo: str | None = None,
               expand: bool = True, extra_terms: list[str] | None = None) -> list[Hit]:
        terms = tokenizer.expand_query(query) if expand else tokenizer.tokenize(query)
        if extra_terms:
            for t in extra_terms:
                terms.extend(tokenizer.tokenize(t))
        q = Counter(terms)
        focus = set(tokenizer.detect_repos(query)) if not repo else set()
        wants_tests = bool(TEST_WORDS & set(terms))
        scores: dict[int, float] = defaultdict(float)
        matched: dict[int, list[str]] = defaultdict(list)
        for term, qtf in q.items():
            plist = self.postings.get(term)
            if not plist:
                continue
            w = self.idf(term) * (1 + 0.3 * (qtf - 1))
            for i, tf in plist:
                dl = self.lengths[i]
                scores[i] += w * tf * (K1 + 1) / (tf + K1 * (1 - B + B * dl / self.avg_len))
                matched[i].append(term)
        ranked: list[tuple[float, int]] = []
        for i, s in scores.items():
            c = self.chunks[i]
            if repo and c["repo"] != repo:
                continue
            if c["repo"] in focus:

            scores[i] += w * tf * (K1 + 1) / (tf + K1 * (1 - B + B * dl / self.avg_len))
            matched[i].append(term)
    ranked: list[tuple[float, int]] = []
    for i, s in scores.items():
        c = self.chunks[i]
        if repo and c["repo"] != repo:
            continue
        if c["repo"] in focus:
            s *= REPO_BOOST
        if c["path"].lower().endswith("readme.md"):
            s *= README_BOOST
        if not wants_tests and is_test_path(c["path"]):
            s *= TEST_PENALTY
        ranked.append((s, i))
    ranked.sort(reverse=True)
    out: list[Hit] = []
    per_file: Counter = Counter()
    for s, i in ranked:
        c = self.chunks[i]
        key = (c["repo"], c["path"])
        if per_file[key] >= MAX_PER_FILE:
            continue
        per_file[key] += 1
        out.append(Hit(c, s, sorted(set(matched[i]))))
        if len(out) >= k:
            break
    return out

def github_url(self, chunk: dict) -> str:
    r = self.repos.get(chunk["repo"], {})
    if not r.get("url"):
        return ""
    return f'{r["url"]}/blob/{r.get("branch") or "main"}/{chunk["path"]}#L{chunk["start"]}-L{chunk["end"]}'

class State:
    """The live index. Sync swaps it under a lock; requests read a reference."""

    def __init__(self) -> None:
        self.lock = threading.Lock()
        self.index = Index.load(KB_PATH) if KB_PATH.exists() else Index({"repos": [], "chunks": []})
        self.sync: GitHubSync | None = None

    def swap(self, kb: dict) -> None:
        new = Index(kb)
        with self.lock:
            self.index = new


STATE = State()


class RateLimiter:
    def __init__(self, limit: int, window_s: int = 600):
        self.limit, self.window = limit, window_s
        self.hits: dict[str, deque] = defaultdict(deque)
        self.lock = threading.Lock()

    def allow(self, key: str) -> bool:
        now = time.time()
        with self.lock:
            q = self.hits[key]
            while q and now - q[0] > self.window:
                q.popleft()
            if len(q) >= self.limit:
                return False
            q.append(now)
            return True


LIMITER = RateLimiter(int(os.environ.get("RATE_LIMIT", "30")))


def source_payload(index: Index, hits) -> list[dict]:
    out = []
    for n, h in enumerate(hits, 1):
        d = h.to_dict(n)
        d["url"] = index.github_url(h.chunk) if h.chunk["path"] != "(overview)" else index.repos.get(h.chunk["repo"], {}).get("url", "")
        out.append(d)
    return out


