def do_POST(self):
    p = urlparse(self.path).path
    try:
        if p == "/api/chat":
            return self.chat()
        if p == "/api/search":
            data = json.loads(self._body() or b"{}")
            return self._json(self.search(data.get("q", ""), data.get("repo"), int(data.get("k", 6))))
        if p == "/api/sync":
            return self.sync_now()
        if p == "/api/webhook/github":
            return self.webhook()
    except (ValueError, json.JSONDecodeError) as e:
        return self._json({"error": str(e)}, 400)
    self._json({"error": "not found"}, 404)

def sync_now(self):
    token = os.environ.get("SYNC_TOKEN")
    if token and self.headers.get("Authorization") != f"Bearer {token}":
        return self._json({"error": "unauthorized"}, 401)
    if not STATE.sync:
        return self._json({"error": "sync is off (no GITHUB_USER)"}, 409)
    STATE.sync.trigger()
    return self._json({"ok": True, "status": STATE.sync.status}, 202)

def webhook(self):
    body = self._body(5_000_000)
    secret = os.environ.get("WEBHOOK_SECRET", "")
    if not secret:
        return self._json({"error": "WEBHOOK_SECRET is not set"}, 403)
    sig = self.headers.get("X-Hub-Signature-256", "")
    expected = "sha256=" + hmac.new(secret.encode(), body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(sig, expected):
        return self._json({"error": "bad signature"}, 401)
    event = self.headers.get("X-GitHub-Event", "")
    if event in ("push", "repository", "create", "delete", "public", "release") and STATE.sync:
        STATE.sync.trigger()
        return self._json({"ok": True, "event": event, "sync": "scheduled"}, 202)
    return self._json({"ok": True, "event": event, "sync": "ignored"})

def chat(self):
    if not LIMITER.allow(self._client_ip()):
        return self._json({"error": "rate_limited", "message": "Too many questions, try again in a few minutes."}, 429)
    data = json.loads(self._body() or b"{}")
    messages = data.get("messages") or []
    repo = data.get("repo") or None
    question, search_text = retrieval_query(messages)
    if not question:
        return self._json({"error": "empty question"}, 400)

"""Keep the knowledge base in step with a GitHub account.

Every SYNC_INTERVAL minutes (and whenever a webhook or the UI asks) we list the
user's public repositories and compare each repo's ``pushed_at`` time with the
one stored in kb.json:

* a new repo        -> cloned and indexed
* a repo with new commits -> pulled and re-indexed (only that repo)
* a deleted / archived repo -> dropped from the index

The new kb.json is written atomically and handed to ``on_update`` so the
running server swaps in the new index without a restart.
"""
from __future__ import annotations

import json
import threading
import time
from pathlib import Path
from typing import Callable

from . import ingest


class GitHubSync:
    def __init__(self, user: str, kb_path: Path, interval_min: float = 30,
                 on_update: Callable[[dict], None] | None = None):
        self.user = user
        self.kb_path = Path(kb_path)
        self.interval = max(1.0, float(interval_min)) * 60
        self.on_update = on_update
        self._lock = threading.Lock()
        self._wake = threading.Event()
        self.status: dict = {"user": user, "enabled": True, "interval_min": self.interval / 60,
                             "last_check": None, "last_change": None, "last_error": None,
                             "running": False, "last_result": None}

    # ------------------------------------------------------------------ core
    def _load(self) -> dict:
        if self.kb_path.exists():
            return json.loads(self.kb_path.read_text(encoding="utf-8"))
        return {"repos": [], "chunks": []}

    def check(self, force: bool = False) -> dict:
        """One sync pass. Returns {"added": [...], "updated": [...], "removed": [...]}."""
        if not self._lock.acquire(blocking=False):
            return {"busy": True}
        self.status["running"] = True
        try:
            listed = ingest.list_user_repos_meta(self.user)
            kb = self._load()
            repos = {r["key"]: r for r in kb["repos"]}
            chunks_by_repo: dict[str, list[dict]] = {}
            for c in kb["chunks"]:
                chunks_by_repo.setdefault(c["repo"], []).append(c)

def _normalize(text: str) -> str:
    text = unicodedata.normalize("NFKC", text)
    text = NIQQUD_RE.sub("", text)
    return text


def _split_identifier(raw: str) -> list[str]:
    """findPathStep / chase_range / HTTP2Server -> its lower-case parts."""
    parts: list[str] = []
    for piece in raw.split("_"):
        if not piece:
            continue
        # Boundaries: lower->Upper, letter<->digit, UPPER->Upper+lower (HTTPServer).
        piece = re.sub(r"([a-z])([A-Z])", r"\1 \2", piece)
        piece = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\1 \2", piece)
        piece = re.sub(r"([A-Za-z])([0-9])|([0-9])([A-Za-z])", lambda m: " ".join(g for g in m.groups() if g), piece)
        parts.extend(p.lower() for p in piece.split() if p)
    return parts


def _hebrew_variants(word: str) -> list[str]:
    out = [word]
    stems = [word]
    if len(word) >= 5 and word[:2] in HE_PREFIX_2:
        stems.append(word[2:])
    if len(word) >= 4 and word[0] in HE_PREFIX_1:
        stems.append(word[1:])
    for s in stems[1:]:
        out.append(s)
    for s in stems:
        if len(s) >= 5 and (s.endswith("ים") or s.endswith("ות")):
            out.append(s[:-2])
    # keep order, drop duplicates
    seen: set[str] = set()
    return [w for w in out if not (w in seen or seen.add(w))]


def tokenize(text: str) -> list[str]:
    """Tokens for indexing and for queries. Duplicates are kept (they carry term frequency)."""
    text = _normalize(text)
    tokens: list[str] = []
    # Identifiers are split before lower-casing, so camelCase boundaries survive.
    for m in re.finditer(r"[A-Za-z0-9_]+|[א-ת]+", text):
        raw = m.group(0)
        if "א" <= raw[0] <= "ת":
            for w in _hebrew_variants(raw):
                if w not in STOPWORDS and len(w) > 1:
                    tokens.append(w)
            continue
        low = raw.lower()
        if low in STOPWORDS or len(low) < 2 or len(low) > 40:
            continue
        tokens.append(low)
        parts = _split_identifier(raw)
        if len(parts) > 1:
            tokens.extend(p for p in parts if len(p) > 1 and p not in STOPWORDS)
    return tokens

