/** Tiny inline SVG chart for the trainee screens (keeps Recharts out of the trainee bundle, 6.3.1). */
export function Sparkline({ values, height = 56 }: { values: number[]; height?: number }) {
  if (values.length < 2) return <div className="muted small">אין עדיין מספיק אימונים לגרף</div>;
  const w = 300;
  const min = Math.min(...values, 0), max = Math.max(...values, 100);
  const x = (i: number) => w - (i / (values.length - 1)) * w; // time runs right to left
  const y = (v: number) => height - ((v - min) / (max - min || 1)) * (height - 6) - 3;
  const d = values.map((v, i) => `${i ? "L" : "M"}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(" ");
  return (
    <svg viewBox={`0 0 ${w} ${height}`} width="100%" height={height} role="img" aria-label="ציון טכניקה לאורך זמן">
      <path d={d} fill="none" stroke="var(--accent)" strokeWidth={2.5} strokeLinejoin="round" />
      {values.map((v, i) => (
        <circle key={i} cx={x(i)} cy={y(v)} r={3} fill="var(--accent)" />
      ))}
    </svg>
  );
}

/** Virtualized list (6.3.1): only the rows on screen exist in the DOM. */
import { useVirtualizer } from "@tanstack/react-virtual";
import { ReactNode, useRef } from "react";

export function VirtualList<T>({ items, rowHeight = 64, height = 480, render, empty }: { items: T[]; rowHeight?: number; height?: number; render: (item: T, i: number) => ReactNode; empty?: ReactNode }) {
  const parent = useRef<HTMLDivElement>(null);
  const v = useVirtualizer({ count: items.length, getScrollElement: () => parent.current, estimateSize: () => rowHeight, overscan: 6 });
  if (!items.length) return <>{empty ?? <div className="muted">אין נתונים</div>}</>;
  return (
    <div ref={parent} className="vlist" style={{ maxHeight: height }}>
      <div style={{ height: v.getTotalSize(), position: "relative" }}>
        {v.getVirtualItems().map((row) => (
          <div key={row.key} data-index={row.index} ref={v.measureElement} style={{ position: "absolute", top: 0, insetInlineStart: 0, width: "100%", transform: `translateY(${row.start}px)` }}>
            {render(items[row.index], row.index)}
          </div>
        ))}
      </div>
    </div>
  );
}

/**
 * The free cloud server sleeps after ~15 minutes without use and needs up to a minute to wake. The app shell opens
 * at once (service worker); this banner pings the API right away and, if it is slow, says what is happening.
 */
import { useEffect, useState } from "react";

export default function WakeBanner() {
  const [state, setState] = useState<"checking" | "waking" | "ok">("checking");
  const [secs, setSecs] = useState(0);

  useEffect(() => {
    let alive = true;
    const slow = window.setTimeout(() => alive && setState((s) => (s === "checking" ? "waking" : s)), 1500);
    const tick = window.setInterval(() => alive && setSecs((n) => n + 1), 1000);
    const ping = async () => {
      for (let i = 0; i < 40 && alive; i++) {
        try {
          const r = await fetch("/api/health", { cache: "no-store" });
          if (r.ok) {
            if (alive) setState("ok");
            return;
          }
        } catch {
          /* still waking */
        }
        await new Promise((res) => setTimeout(res, 2500));
      }
    };
    void ping();
    return () => {
      alive = false;
      clearTimeout(slow);
      clearInterval(tick);
    };
  }, []);

  if (state !== "waking") return null;
  return (
    <div className="banner warn" role="status" data-testid="wake-banner">
      ⏳ השרת מתעורר (בגרסה החינמית הוא נרדם כשאין שימוש)… {secs} שניות. בדרך כלל עד דקה, ואחר כך הכל מהיר.
    </div>
  );
}

