        </div>
        <div className="listrow small muted" style={{ fontWeight: 600 }}>
          {th("name", "שם")}
          {th("last_session", "אימון אחרון")}
          {th("avg_score", "ציון (4 שבועות)")}
          {th("trend_pct", "מגמה")}
          {th("alerts", "התראות")}
