import { memo } from 'react'
import type { GameState, Pos, Tile } from '../types/game'
import { findLieAt, isVisible, trueTileAt } from '../utils/gameLogic'
import { TileIcon } from './TileIcon'

interface Props {
  state: GameState
  cell: number
  flash: { cells: Pos[]; kind: 'wrong' | 'caught'; id: number } | null
  onCellClick: (p: Pos) => void
  shake: boolean
}

const tileBg: Record<Tile, string> = {
  wall: 'tile-wall',
  floor: 'tile-floor',
  trap: 'tile-floor',
  exit: 'tile-floor',
  treasure: 'tile-floor',
}

function GameBoardImpl({ state, cell, flash, onCellClick, shake }: Props) {
  const { level, player, explored, revealed, caught, phase } = state
  const showAllLies = phase === 'won'

  const cells = []
  for (let y = 0; y < level.height; y++) {
    for (let x = 0; x < level.width; x++) {
      const p = { x, y }
      const visible = revealed || isVisible(state, p)
      const seen = explored[y][x]
      const tile = trueTileAt(state, p)
      const lie = findLieAt(level, p)
      const isCaught = lie !== undefined && caught.has(lie.id)
      const missed = showAllLies && lie !== undefined && !isCaught
      const flashing = flash && flash.cells.some((c) => c.x === x && c.y === y)

      let cls = 'relative flex items-center justify-center select-none '
      if (!seen && !visible) cls += 'tile-dark'
      else {
        cls += tileBg[tile]
        if (!visible) cls += ' tile-dim'
      }

      cells.push(
        <div
          key={`${x},${y}`}
          data-x={x}
          data-y={y}
          className={cls}
          style={{ width: cell, height: cell }}
          onClick={() => onCellClick(p)}
        >
          {(seen || visible) && <TileIcon tile={tile} />}
          {isCaught && <div className="lie-caught pointer-events-none absolute inset-0" />}
          {missed && <div className="lie-missed pointer-events-none absolute inset-0" />}
          {flash && flashing && (
            <div
              key={flash.id}
              className={`pointer-events-none absolute inset-0 ${flash.kind === 'wrong' ? 'flash-wrong' : 'flash-caught'}`}

        >
          {(seen || visible) && <TileIcon tile={tile} />}
          {isCaught && <div className="lie-caught pointer-events-none absolute inset-0" />}
          {missed && <div className="lie-missed pointer-events-none absolute inset-0" />}
          {flash && flashing && (
            <div
              key={flash.id}
              className={`pointer-events-none absolute inset-0 ${flash.kind === 'wrong' ? 'flash-wrong' : 'flash-caught'}`}
            />
          )}
        </div>,
      )
    }
  }

  const half = cell / 2
  return (
    <div
      dir="ltr"
      className={`board relative overflow-hidden rounded-lg border border-zinc-800 bg-black shadow-2xl ${shake ? 'shake' : ''}`}
      style={{ width: level.width * cell, height: level.height * cell }}
    >
      <div
        className="grid"
        style={{ gridTemplateColumns: `repeat(${level.width}, ${cell}px)`, gridAutoRows: `${cell}px` }}
      >
        {cells}
      </div>
      {/* Lantern glow */}
      <div
        className="lantern pointer-events-none absolute"
        style={{
          width: cell * 5,
          height: cell * 5,
          left: player.x * cell + half - cell * 2.5,
          top: player.y * cell + half - cell * 2.5,
        }}
      />
      {/* Player */}
      <div
        className={`player pointer-events-none absolute flex items-center justify-center ${phase === 'dead' ? 'player-dead' : ''}`}
        style={{ width: cell, height: cell, left: player.x * cell, top: player.y * cell }}
      >
        <div className="player-core" style={{ width: cell * 0.5, height: cell * 0.5 }} />
      </div>
    </div>
  )
}

export const GameBoard = memo(GameBoardImpl)

import { memo } from 'react'
import type { GameState, Pos, Tile } from '../types/game'
import { findLieAt, mapTileAt } from '../utils/gameLogic'
import type { Strings } from '../i18n'

interface Props {
  state: GameState
  angry: boolean
  size: number
  t: Strings
  onCellClick: (p: Pos) => void
}

const color: Record<Tile, string> = {
  wall: 'mm-wall',
  floor: 'mm-floor',
  trap: 'mm-trap',
  exit: 'mm-exit',
  treasure: 'mm-treasure',
}

function MinimapImpl({ state, angry, size, t, onCellClick }: Props) {
  const { level, player, caught, revealed } = state
  const cell = Math.max(5, Math.floor(size / Math.max(level.width, level.height)))
  const cells = []
  for (let y = 0; y < level.height; y++)
    for (let x = 0; x < level.width; x++) {
      const p = { x, y }
      const tile = mapTileAt(state, p)
      const lie = findLieAt(level, p)
      const fixed = lie !== undefined && caught.has(lie.id)
      cells.push(
        <div
          key={`${x},${y}`}
          data-mx={x}
          data-my={y}
          className={`${color[tile]} ${fixed ? 'mm-fixed' : ''} cursor-crosshair`}
          style={{ width: cell, height: cell }}
          onClick={() => onCellClick(p)}
        />,
      )
    }

  const status = revealed ? t.confessed : angry ? t.angry : t.calm
  return (
    <div className={`minimap-frame ${angry ? 'minimap-angry' : ''} ${revealed ? 'minimap-confessed' : ''}`}>
      <div className="mb-1.5 flex items-center justify-between gap-2 px-1 text-xs">
        <span className="font-semibold tracking-wide text-zinc-300">{t.minimap}</span>
        <span
          className={`rounded px-1.5 py-0.5 text-[10px] font-semibold ${
            revealed ? 'bg-emerald-900/60 text-emerald-300' : angry ? 'bg-red-900/70 text-red-200' : 'bg-zinc-800 text-zinc-400'
          }`}
        >
          {status}
        </span>
      </div>
      <div dir="ltr" className="minimap-screen relative overflow-hidden rounded">
        <div className={`grid ${angry ? 'glitch' : ''}`} style={{ gridTemplateColumns: `repeat(${level.width}, ${cell}px)` }}>
          {cells}
        </div>

        >
          {status}
        </span>
      </div>
      <div dir="ltr" className="minimap-screen relative overflow-hidden rounded">
        <div className={`grid ${angry ? 'glitch' : ''}`} style={{ gridTemplateColumns: `repeat(${level.width}, ${cell}px)` }}>
          {cells}
        </div>
        <div
          className="mm-player pointer-events-none absolute"
          style={{ width: cell, height: cell, left: player.x * cell, top: player.y * cell }}
        />
        <div className="scanlines pointer-events-none absolute inset-0" />
        {angry && <div className="static-noise pointer-events-none absolute inset-0" />}
      </div>
    </div>
  )
}

export const Minimap = memo(MinimapImpl)

