# ------------------------------------------------------------- input
def handle_event(self, event) -> None:
    if event.type == pygame.QUIT:
        self.running = False
        return
    if event.type != pygame.KEYDOWN:
        return
    handler = {
        Screen.MENU: self._menu_key,
        Screen.GAME: self._game_key,
        Screen.NAME_ENTRY: self._name_key,
        Screen.HIGHSCORES: self._highscores_key,
    }[self.current]
    handler(event)

def _menu_key(self, event) -> None:
    item = MENU_ITEMS[self.menu_index]
    if event.key in (pygame.K_UP, pygame.K_w):
        self.menu_index = (self.menu_index - 1) % len(MENU_ITEMS)
        self.sound.play("menu_move")
    elif event.key in (pygame.K_DOWN, pygame.K_s):
        self.menu_index = (self.menu_index + 1) % len(MENU_ITEMS)
        self.sound.play("menu_move")
    elif event.key in (pygame.K_LEFT, pygame.K_RIGHT, pygame.K_a, pygame.K_d) and \
            item in ("language", "sound"):
        self._activate(item)
    elif event.key in CONFIRM_KEYS:
        self._activate(item)
    elif event.key == pygame.K_ESCAPE:
        self.running = False

    elif event.key in (pygame.K_LEFT, pygame.K_RIGHT, pygame.K_a, pygame.K_d) and \
            item in ("language", "sound"):
        self._activate(item)
    elif event.key in CONFIRM_KEYS:
        self._activate(item)
    elif event.key == pygame.K_ESCAPE:
        self.running = False

def _activate(self, item: str) -> None:
    self.sound.play("menu_select")
    if item == "start":
        self.game.start_new_game()
        self.current = Screen.GAME
        self.sound.start_music()
    elif item == "language":
        self.toggle_language()
    elif item == "sound":
        self.toggle_sound()
    elif item == "highscores":
        self.highlight_rank = None
        self.current = Screen.HIGHSCORES
    else:
        self.running = False

def _game_key(self, event) -> None:
    state = self.game.state
    if event.key == pygame.K_m:
        self.toggle_sound()
    elif event.key in (pygame.K_p, pygame.K_ESCAPE) and state in (GameState.PLAYING, GameState.PAUSED):
        self.game.toggle_pause()
        self.sound.pause_music(self.game.state is GameState.PAUSED)
    elif event.key == pygame.K_q and state is GameState.PAUSED:
        self.sound.stop_music()
        self.current = Screen.MENU
    elif event.key == pygame.K_SPACE and state is GameState.PLAYING:
        self.bomb_pressed = True
    elif event.key in CONFIRM_KEYS and state in (GameState.GAME_OVER, GameState.VICTORY):
        if self.highscores.qualifies(self.game.score):
            self.name_buffer = ""
            self.current = Screen.NAME_ENTRY
        else:
            self.highlight_rank = None
            self.current = Screen.HIGHSCORES

def _name_key(self, event) -> None:
    if event.key in CONFIRM_KEYS:
        self.highlight_rank = self.highscores.add(self.name_buffer, self.game.score)
        self.sound.play("menu_select")
        self.current = Screen.HIGHSCORES
    elif event.key == pygame.K_BACKSPACE:
        self.name_buffer = self.name_buffer[:-1]
    elif event.unicode and event.unicode.isprintable() and \
            len(self.name_buffer) < config.MAX_NAME_LENGTH:
        self.name_buffer += event.unicode

def _highscores_key(self, event) -> None:
    if event.key in CONFIRM_KEYS or event.key == pygame.K_ESCAPE:
        self.current = Screen.MENU

"""Things that live on the grid: the player, enemies, bombs and power-ups."""
from __future__ import annotations

from dataclasses import dataclass
from enum import Enum

from . import config


class Direction(Enum):
    UP = (0, -1)
    DOWN = (0, 1)
    LEFT = (-1, 0)
    RIGHT = (1, 0)

    @property
    def dx(self) -> int:
        return self.value[0]

    @property
    def dy(self) -> int:
        return self.value[1]

    @property
    def opposite(self) -> "Direction":
        return {
            Direction.UP: Direction.DOWN,
            Direction.DOWN: Direction.UP,
            Direction.LEFT: Direction.RIGHT,
            Direction.RIGHT: Direction.LEFT,
        }[self]


class PowerUpType(Enum):
    BOMB_UP = "bomb_up"    # +1 bomb at a time
    FIRE_UP = "fire_up"    # +1 explosion range
    SPEED_UP = "speed_up"  # faster movement


class Mover:
    """Tile-based movement with a cooldown. The logical position jumps one
    tile at a time; render_pos() interpolates so movement looks smooth."""

    def __init__(self, x: int, y: int, speed: float):
        self.x = x
        self.y = y
        self.prev_x = x
        self.prev_y = y
        self.speed = speed
        self.cooldown = 0.0
        self.facing = Direction.DOWN

    @property
    def pos(self) -> tuple[int, int]:
        return (self.x, self.y)

    def can_move(self) -> bool:
        return self.cooldown <= 0.0

    @property
    def pos(self) -> tuple[int, int]:
        return (self.x, self.y)

    def can_move(self) -> bool:
        return self.cooldown <= 0.0

    def move(self, direction: Direction) -> None:
        self.prev_x, self.prev_y = self.x, self.y
        self.x += direction.dx
        self.y += direction.dy
        self.facing = direction
        self.cooldown = 1.0 / self.speed

    def tick(self, dt: float) -> None:
        self.cooldown = max(0.0, self.cooldown - dt)

    def place_at(self, x: int, y: int) -> None:
        self.x = self.prev_x = x
        self.y = self.prev_y = y
        self.cooldown = 0.0
        self.facing = Direction.DOWN

    def render_pos(self) -> tuple[float, float]:
        if self.cooldown <= 0.0:
            return (float(self.x), float(self.y))
        t = min(1.0, max(0.0, 1.0 - self.cooldown * self.speed))
        return (
            self.prev_x + (self.x - self.prev_x) * t,
            self.prev_y + (self.y - self.prev_y) * t,
        )


class Player(Mover):
    def __init__(self, x: int = 0, y: int = 0):
        super().__init__(x, y, config.PLAYER_BASE_SPEED)
        self.lives = config.PLAYER_START_LIVES
        self.max_bombs = config.PLAYER_START_BOMBS
        self.fire_range = config.PLAYER_START_FIRE
        self.alive = True

    def apply_powerup(self, kind: PowerUpType) -> None:
        if kind is PowerUpType.BOMB_UP:
            self.max_bombs = min(config.PLAYER_MAX_BOMBS, self.max_bombs + 1)
        elif kind is PowerUpType.FIRE_UP:
            self.fire_range = min(config.PLAYER_MAX_FIRE, self.fire_range + 1)
        elif kind is PowerUpType.SPEED_UP:
            self.speed = min(config.PLAYER_MAX_SPEED, self.speed + config.PLAYER_SPEED_STEP)

        if kind is PowerUpType.BOMB_UP:
            self.max_bombs = min(config.PLAYER_MAX_BOMBS, self.max_bombs + 1)
        elif kind is PowerUpType.FIRE_UP:
            self.fire_range = min(config.PLAYER_MAX_FIRE, self.fire_range + 1)
        elif kind is PowerUpType.SPEED_UP:
            self.speed = min(config.PLAYER_MAX_SPEED, self.speed + config.PLAYER_SPEED_STEP)


class Enemy(Mover):
    def __init__(self, kind: str, x: int, y: int):
        if kind not in config.ENEMY_STATS:
            raise ValueError(f"unknown enemy kind: {kind}")
        stats = config.ENEMY_STATS[kind]
        super().__init__(x, y, stats["speed"])
        self.kind = kind
        self.points = stats["points"]
        self.chase_range = stats["chase_range"]
        self.alive = True
        self.direction: Direction | None = None


@dataclass(eq=False)  # identity equality: two bombs are never "the same"
class Bomb:
    x: int
    y: int
    fire_range: int
    timer: float = config.BOMB_FUSE

    @property
    def pos(self) -> tuple[int, int]:
        return (self.x, self.y)

    self.rng = rng or random.Random()
    self.state = GameState.MENU
    self.score = 0
    self.level_index = 0
    self.player = Player()
    self.events: list[str] = []  # things that happened this frame (for sound / UI)
    self._reset_level_objects()

# ------------------------------------------------------------------ setup
def _reset_level_objects(self) -> None:
    self.grid: Grid = self.levels[0].grid.copy()
    self.enemies: list[Enemy] = []
    self.bombs: list[Bomb] = []
    self.flames: dict[tuple[int, int], float] = {}
    self.powerups: dict[tuple[int, int], PowerUpType] = {}
    self.hidden_powerups: dict[tuple[int, int], PowerUpType] = {}
    self.exit_pos: tuple[int, int] = self.levels[0].exit_pos
    self.exit_revealed = False
    self.time_left = config.LEVEL_TIME
    self.state_timer = 0.0

def start_new_game(self) -> None:
    self.score = 0
    self.level_index = 0
    self.player = Player()
    self._load_level(0)
    self.state = GameState.PLAYING

def _load_level(self, index: int) -> None:
    data = self.levels[index]
    self.level_index = index
    self._reset_level_objects()
    self.grid = data.grid.copy()
    self.enemies = [Enemy(kind, x, y) for kind, (x, y) in data.enemies]
    self.hidden_powerups = dict(data.powerups)
    self.exit_pos = data.exit_pos
    self.player.place_at(*data.player_start)
    self.player.alive = True

# -------------------------------------------------------------- queries
@property
